do $$
declare
  u uuid := gen_random_uuid(); w uuid; c uuid := gen_random_uuid();
  q uuid := gen_random_uuid(); again uuid := gen_random_uuid(); newer uuid := gen_random_uuid(); late uuid := gen_random_uuid();
  older uuid := gen_random_uuid(); branch uuid := gen_random_uuid(); edited uuid := gen_random_uuid();
begin
  insert into auth.users(id,email) values(u,'qa-'||u||'@example.invalid');
  select id into strict w from public.workspaces where owner_id=u;
  perform set_config('request.jwt.claim.sub',u::text,true);
  insert into public.conversations(id,workspace_id,title) values(c,w,'Synthetic regenerate');
  perform public.start_chat_request(q,c,'Synthetic question','{}');
  perform public.finish_chat_request(q,'completed','First answer');
  perform public.start_chat_request(again,c,'Synthetic question','{}',q);
  perform public.finish_chat_request(again,'completed','Second answer');
  if (select count(*) from public.messages where conversation_id=c and role='user') <> 1 then raise exception 'Regenerating must not add a second question'; end if;
  if (select count(*) from public.messages where conversation_id=c and role='assistant' and answer_of=q) <> 2 then raise exception 'Both answers must stay and belong to the first question'; end if;
  begin
    perform public.start_chat_request(late,c,'Another question','{}',q);
    raise exception 'A different question must not be regenerated as the first';
  exception when sqlstate '22023' then null; end;

  perform public.start_chat_request(newer,c,'Next question','{}');
  perform public.finish_chat_request(newer,'completed','Next answer');
  if (select parent_id from public.chat_requests where id=newer) is distinct from again then raise exception 'A new question must follow the newest answer'; end if;

  perform public.start_chat_request(older,c,'Synthetic question','{}',q);
  perform public.finish_chat_request(older,'completed','Third answer');
  if (select parent_id from public.chat_requests where id=older) is not null then raise exception 'An earlier question must stay regenerable and keep its place'; end if;

  perform public.start_chat_request(branch,c,'Branch question','{}',null,q);
  if (select parent_id from public.chat_requests where id=branch) is distinct from q then raise exception 'Continuing must follow the answer being viewed'; end if;
  if (select chat_request_id from public.messages where request_id=branch) is distinct from branch then raise exception 'A question must belong to its request'; end if;
  perform public.finish_chat_request(branch,'completed','Branch answer');

  perform public.start_chat_request(edited,c,'Edited question','{}',null,null,newer);
  if (select parent_id from public.chat_requests where id=edited) is distinct from again then raise exception 'An edit must branch where the edited question was asked'; end if;
  if (select content from public.messages where request_id=newer) <> 'Next question' then raise exception 'Editing must keep the original question'; end if;
  if (select content from public.messages where request_id=edited) <> 'Edited question' then raise exception 'An edit must save the new question'; end if;
end;
$$;

export type ChatNode = { id: string; parent: string | null; regenerates: string | null; created_at: string };
export type PathStep = { after: string | null; question: string; answer: string; questions: string[]; answers: string[] };
export type ChatPicks = Record<string, string>;

export const questionPick = (step: Pick<PathStep, "after" | "questions">) => `after:${step.after ?? "start"}:${step.questions.length}`;
export const answerPick = (step: Pick<PathStep, "question" | "answers">) => `of:${step.question}:${step.answers.length}`;

export function ancestors(nodes: ChatNode[], leaf: string | null): ChatNode[] {
  const byId = new Map(nodes.map(node => [node.id, node]));
  const path: ChatNode[] = [];
  for (let node = leaf ? byId.get(leaf) : undefined; node && !path.includes(node); node = node.parent ? byId.get(node.parent) : undefined) path.push(node);
  return path.reverse();
}

export function visiblePath(nodes: ChatNode[], picks: ChatPicks = {}): PathStep[] {
  const sorted = [...nodes].sort((a, b) => a.created_at.localeCompare(b.created_at) || a.id.localeCompare(b.id));
  const known = new Set(sorted.map(node => node.id));
  const children = new Map<string, ChatNode[]>();
  for (const node of sorted) {
    const key = node.parent && known.has(node.parent) ? node.parent : "";
    children.set(key, [...children.get(key) ?? [], node]);
  }
  const newest = new Map<string, string>();
  const latest = (node: ChatNode, seen = new Set<string>()): string => {
    const cached = newest.get(node.id);
    if (cached) return cached;
    seen.add(node.id);
    const value = (children.get(node.id) ?? []).filter(child => !seen.has(child.id)).reduce((max, child) => { const time = latest(child, seen); return time > max ? time : max; }, node.created_at);
    newest.set(node.id, value);
    return value;
  };
  const newestOf = (options: ChatNode[], score: (node: ChatNode) => string) => options.reduce((best, node) => score(node) >= score(best) ? node : best);
  const steps: PathStep[] = [];
  const visited = new Set<string>();
  for (let after: string | null = null; ;) {
    const here = children.get(after ?? "") ?? [];
    const questions = here.filter(node => !node.regenerates || !here.some(other => other.id === node.regenerates));
    if (!questions.length) break;
    const versionsOf = (question: ChatNode) => here.filter(node => node.id === question.id || node.regenerates === question.id);
    const ids = questions.map(node => node.id);
    const question = questions.find(node => node.id === picks[questionPick({ after, questions: ids })])
      ?? newestOf(questions, node => versionsOf(node).map(version => latest(version)).sort().at(-1) ?? node.created_at);
    const versions = versionsOf(question);
    const answers = versions.map(node => node.id);
    const answer = versions.find(node => node.id === picks[answerPick({ question: question.id, answers })]) ?? newestOf(versions, node => latest(node));
    if (visited.has(answer.id)) break;
    visited.add(answer.id);
    steps.push({ after, question: question.id, answer: answer.id, questions: ids, answers });
    after = answer.id;
  }
  return steps;
}

export type ChatNode = { id: string; parent: string | null; regenerates: string | null; created_at: string };
export type PathStep = { after: string | null; question: string; answer: string; questions: string[]; answers: string[] };
export type ChatPicks = Record<string, string>;

export const questionPick = (step: Pick<PathStep, "after" | "questions">) => `after:${step.after ?? "start"}:${step.questions.length}`;
export const answerPick = (step: Pick<PathStep, "question" | "answers">) => `of:${step.question}:${step.answers.length}`;

export function ancestors(nodes: ChatNode[], leaf: string | null): ChatNode[] {
  const byId = new Map(nodes.map(node => [node.id, node]));
  const path: ChatNode[] = [];
  for (let node = leaf ? byId.get(leaf) : undefined; node; node = node.parent ? byId.get(node.parent) : undefined) path.push(node);
  return path.reverse();
}

export function visiblePath(nodes: ChatNode[], picks: ChatPicks = {}): PathStep[] {
  const sorted = [...nodes].sort((a, b) => a.created_at.localeCompare(b.created_at) || a.id.localeCompare(b.id));
  const known = new Set(sorted.map(node => node.id));
  const children = new Map<string, ChatNode[]>();
  for (const node of sorted) {
    const key = node.parent && known.has(node.parent) ? node.parent : "";
    children.set(key, [...children.get(key) ?? [], node]);
  }
  const newest = new Map<string, string>();
  const latest = (node: ChatNode): string => {
    const value = newest.get(node.id) ?? (children.get(node.id) ?? []).map(latest).reduce((max, time) => time > max ? time : max, node.created_at);
    newest.set(node.id, value);
    return value;
  };
  const newestOf = (options: ChatNode[], score: (node: ChatNode) => string) => options.reduce((best, node) => score(node) >= score(best) ? node : best);
  const steps: PathStep[] = [];
  for (let after: string | null = null; ;) {
    const here = children.get(after ?? "") ?? [];
    const questions = here.filter(node => !node.regenerates || !here.some(other => other.id === node.regenerates));
    if (!questions.length) return steps;
    const versionsOf = (question: ChatNode) => here.filter(node => node.id === question.id || node.regenerates === question.id);
    const ids = questions.map(node => node.id);
    const question = questions.find(node => node.id === picks[questionPick({ after, questions: ids })])
      ?? newestOf(questions, node => versionsOf(node).map(latest).reduce((max, time) => time > max ? time : max));
    const versions = versionsOf(question);
    const answers = versions.map(node => node.id);
    const answer = versions.find(node => node.id === picks[answerPick({ question: question.id, answers })]) ?? newestOf(versions, latest);
    steps.push({ after, question: question.id, answer: answer.id, questions: ids, answers });
    after = answer.id;
  }
}

import { expect, it } from "vitest";
import { ancestors, answerPick, questionPick, visiblePath, type ChatNode } from "./chat-tree";

let clock = 0;
const node = (id: string, parent: string | null, regenerates: string | null = null): ChatNode => ({ id, parent, regenerates, created_at: new Date(Date.UTC(2026, 0, 1, 0, 0, ++clock)).toISOString() });
const answers = (nodes: ChatNode[], picks = {}) => visiblePath(nodes, picks).map(step => step.answer);

it("follows the newest reply and the conversation that grew from it", () => {
  clock = 0;
  const nodes = [node("q1", null), node("q2", "q1"), node("q2b", "q1", "q2"), node("q3", "q2b")];
  expect(answers(nodes)).toEqual(["q1", "q2b", "q3"]);
});

it("keeps showing an older reply once the owner continued from it", () => {
  clock = 0;
  const nodes = [node("q1", null), node("q2", "q1"), node("q2b", "q1", "q2"), node("q2c", "q1", "q2"), node("q3", "q2b")];
  expect(answers(nodes)).toEqual(["q1", "q2b", "q3"]);
  expect(answers(nodes, { [answerPick({ question: "q2", answers: ["q2", "q2b", "q2c"] })]: "q2c" })).toEqual(["q1", "q2c"]);
});

it("shows an edited question as a branch beside the original and returns to it on request", () => {
  clock = 0;
  const nodes = [node("q1", null), node("q2", "q1"), node("q3", "q2"), node("edit", "q1")];
  const path = visiblePath(nodes);
  expect(path.map(step => step.answer)).toEqual(["q1", "edit"]);
  expect(path[1]?.questions).toEqual(["q2", "edit"]);
  expect(answers(nodes, { [questionPick({ after: "q1", questions: ["q2", "edit"] })]: "q2" })).toEqual(["q1", "q2", "q3"]);
});

it("drops a choice once a newer version appears at that point", () => {
  clock = 0;
  const nodes = [node("q1", null), node("q1b", null, "q1")];
  const picks = { [answerPick({ question: "q1", answers: ["q1", "q1b"] })]: "q1" };
  expect(answers(nodes, picks)).toEqual(["q1"]);
  expect(answers([...nodes, node("q1c", null, "q1")], picks)).toEqual(["q1c"]);
});

it("replays only the branch that leads to the reply being continued", () => {
  clock = 0;
  const nodes = [node("q1", null), node("q2", "q1"), node("q2b", "q1", "q2"), node("q3", "q2")];
  expect(ancestors(nodes, "q2b").map(item => item.id)).toEqual(["q1", "q2b"]);
  expect(ancestors(nodes, "q3").map(item => item.id)).toEqual(["q1", "q2", "q3"]);
});
